// === Tab: mySketch ===
// Experimenting with applying a shader as a texture
// thanks to nagayama https://www.openprocessing.org/sketch/855457
// The sketch models a borderless flat-screen monitor
// displaying a looping video (generated by the shader)


(function () {
  var loadJS = function(filename){
    var script = document.createElement("script");
    script.setAttribute("type","text/javascript");
    script.setAttribute("src", filename);
    document.getElementsByTagName("head")[0].appendChild(script);
  }
  loadJS("https://freshfork.github.io/p5.SimpleCam/p5.simplecam.min.js");
})();


let theShader;
let W = 800;
let theta = 0;
let s_texture;
let cam;

function preload() {
	theShader = createShader(vert, frag)
}

function setup() {
	createCanvas(1112, 834, WEBGL);
	cam = createSimpleCam();
	cam.zoom = new Damp(-100,-5,0.07,[-600,1000]); // adjust zoom
	cam.rx = new Damp(PI/4,0.01,0.07,[PI/4-PI/2,PI/4+PI/2]); // set initial X rotation
	cam.ry = new Damp(2*PI/3,0.01,0.07,[PI/4-PI/2,PI/4+PI/2]); // set initial Z rotation
	s_texture = createGraphics(width, height, WEBGL)
	noStroke();
	s_texture.noStroke()
}

function draw() {
	cam.apply();
	background(0,40,40)
	theShader.setUniform("r", [width, height]);
	theShader.setUniform("t", millis() / 1000.0);

	s_texture.shader(theShader);
	//shader(theShader)
	s_texture.rect(0, 0, width, height);

	theta += 0.1
	scale(2);
	push()
	rotateX(theta)
	//rotateZ(theta)
	texture(s_texture)
	box(200,200,10);
	pop()
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

const vert = `
attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  gl_Position = positionVec4;
}
`

    const frag = `
precision mediump float;
uniform float t;
uniform vec2  r;
void main(void) {
	vec2 p = (gl_FragCoord.xy - r) / min(r.x, r.y);
	vec3 destColor = vec3(0.0);
	for(float i=0.0; i < 6.0; i++) {
		float j = i+1.;
		vec2 q = p + vec2(cos(t*j), sin(t*j)) * .5;
		destColor.x += 0.01 / length(q);
		destColor.y += 0.03 / length(q);
		destColor.z += 0.08 / length(q);
	}
	gl_FragColor = vec4(destColor,1.0);
}
`

